(1, 2, 'PHP Insert data into database in php mysql', 'php-insert-data-into-database', '<h2 style=\"font-family: Poppins, sans-serif; color: rgb(33, 37, 41);\">Insert data into database in php mysql</h2><h3><p style=\"margin-bottom: 16px; line-height: 24px; font-size: 16px; color: rgb(33, 37, 41); font-family: Poppins, sans-serif;\"><br></p><p style=\"margin-bottom: 16px; line-height: 24px; font-size: 16px; color: rgb(33, 37, 41); font-family: Poppins, sans-serif;\">In this tutorial, you will learn how to insert data into database in php mysql, where we will create a form, database connection and finally the processing code to save your data in MySQL D<span style=\"font-family: var(--bs-font-sans-serif); font-size: 1rem;\">atabase.</span></p><p style=\"margin-bottom: 16px; line-height: 24px; font-size: 16px; color: rgb(33, 37, 41); font-family: Poppins, sans-serif;\"><span style=\"font-family: var(--bs-font-sans-serif); font-size: 1rem;\">Let\'s create a&nbsp;<span style=\"font-weight: bolder;\">table&nbsp;</span>named as&nbsp;<span style=\"font-weight: bolder;\">students</span>&nbsp;in database as given below:</span></p><div class=\"alert funda-bg\" style=\"width: fit-content; min-width: 100%; background-color: rgb(30, 30, 30); color: rgb(212, 212, 212); font-family: Consolas, &quot;Courier New&quot;, monospace; font-size: 14px; line-height: 19px; white-space: pre;\"><div>CREATE TABLE <span style=\"color: rgb(206, 145, 120);\">`students`</span> (</div><div>&nbsp; &nbsp; id <span style=\"color: rgb(86, 156, 214);\">int</span> NOT <span style=\"color: rgb(86, 156, 214);\">NULL</span> AUTO_INCREMENT,</div><div>&nbsp; &nbsp; fullname <span style=\"color: rgb(220, 220, 170);\">varchar</span>(<span style=\"color: rgb(181, 206, 168);\">55</span>) NOT <span style=\"color: rgb(86, 156, 214);\">NULL</span>,</div><div>&nbsp; &nbsp; course <span style=\"color: rgb(220, 220, 170);\">varchar</span>(<span style=\"color: rgb(181, 206, 168);\">55</span>) NOT <span style=\"color: rgb(86, 156, 214);\">NULL</span>,</div><div>&nbsp; &nbsp; email <span style=\"color: rgb(220, 220, 170);\">varchar</span>(<span style=\"color: rgb(181, 206, 168);\">55</span>) NOT <span style=\"color: rgb(86, 156, 214);\">NULL</span>,</div><div>&nbsp; &nbsp; PRIMARY <span style=\"color: rgb(220, 220, 170);\">KEY</span> (id)</div><div>) &nbsp;ENGINE=InnoDB DEFAULT CHARSET=latin1;</div></div><p style=\"margin-bottom: 16px; line-height: 24px; font-size: 16px; color: rgb(33, 37, 41); font-family: Poppins, sans-serif;\"><span style=\"font-family: var(--bs-font-sans-serif); font-size: 1rem;\"><br></span></p><p style=\"margin-bottom: 16px; line-height: 24px; font-size: 16px; color: rgb(33, 37, 41); font-family: Poppins, sans-serif;\"><span style=\"font-family: var(--bs-font-sans-serif); font-size: 1rem;\">So guys, Lets get started to insert data in database in php mysql:</span></p><p style=\"margin-bottom: 16px; line-height: 24px; font-size: 16px; color: rgb(33, 37, 41); font-family: Poppins, sans-serif;\"><span style=\"font-weight: bolder;\">Step 1:&nbsp;</span>Create a file named&nbsp;<span style=\"font-weight: bolder;\">dbconfig.php</span>&nbsp;to give the database connection in php.</p><div class=\"alert funda-bg\" style=\"width: fit-content; min-width: 100%; background-color: rgb(30, 30, 30); color: rgb(212, 212, 212); font-family: Consolas, &quot;Courier New&quot;, monospace; font-size: 14px; line-height: 19px; white-space: pre;\"><div><span style=\"color: rgb(86, 156, 214);\">&lt;?php</span></div><div>&nbsp; &nbsp; <span style=\"color: rgb(156, 220, 254);\">$host</span> = <span style=\"color: rgb(206, 145, 120);\">\"localhost\"</span>;</div><div>&nbsp; &nbsp; <span style=\"color: rgb(156, 220, 254);\">$username</span> = <span style=\"color: rgb(206, 145, 120);\">\"your_username\"</span>;</div><div>&nbsp; &nbsp; <span style=\"color: rgb(156, 220, 254);\">$password</span> = <span style=\"color: rgb(206, 145, 120);\">\"your_password\"</span>;</div><div>&nbsp; &nbsp; <span style=\"color: rgb(156, 220, 254);\">$database</span> = <span style=\"color: rgb(206, 145, 120);\">\"your_database_name\"</span>;</div><br><div>&nbsp; &nbsp; <span style=\"color: rgb(106, 153, 85);\">// Create DB Connection</span></div><div>&nbsp; &nbsp; <span style=\"color: rgb(156, 220, 254);\">$conn</span> = <span style=\"color: rgb(220, 220, 170);\">mysqli_connect</span>(<span style=\"color: rgb(156, 220, 254);\">$host</span>, <span style=\"color: rgb(156, 220, 254);\">$username</span>, <span style=\"color: rgb(156, 220, 254);\">$password</span>, <span style=\"color: rgb(156, 220, 254);\">$database</span>);</div><br><div>&nbsp; &nbsp; <span style=\"color: rgb(106, 153, 85);\">// Check connection</span></div><div>&nbsp; &nbsp; <span style=\"color: rgb(197, 134, 192);\">if</span> (!<span style=\"color: rgb(156, 220, 254);\">$conn</span>) {</div><div>&nbsp; &nbsp; &nbsp; &nbsp; <span style=\"color: rgb(197, 134, 192);\">die</span>(<span style=\"color: rgb(206, 145, 120);\">\"Connection failed: \"</span> . <span style=\"color: rgb(220, 220, 170);\">mysqli_connect_error</span>());</div><div>&nbsp; &nbsp; }</div><div><span style=\"color: rgb(86, 156, 214);\">?</span><span style=\"color: rgb(86, 156, 214);\">&gt;</span></div></div><p style=\"margin-bottom: 16px; line-height: 24px; font-size: 16px; color: rgb(33, 37, 41); font-family: Poppins, sans-serif;\"><span style=\"font-weight: bolder; font-family: var(--bs-font-sans-serif); font-size: 1rem;\"><br></span></p><p style=\"margin-bottom: 16px; line-height: 24px; font-size: 16px; color: rgb(33, 37, 41); font-family: Poppins, sans-serif;\"><span style=\"font-weight: bolder; font-family: var(--bs-font-sans-serif); font-size: 1rem;\">Step 2:&nbsp;</span><span style=\"font-family: var(--bs-font-sans-serif); font-size: 1rem;\">Create a file named&nbsp;</span><span style=\"font-weight: bolder; font-family: var(--bs-font-sans-serif); font-size: 1rem;\">student.php</span><span style=\"font-family: var(--bs-font-sans-serif); font-size: 1rem;\">&nbsp;to make a HTML FORM. Also we will be using bootstrap v5 to design the FORM.</span><br></p><div class=\"alert funda-bg\" style=\"width: fit-content; min-width: 100%; background-color: rgb(30, 30, 30); color: rgb(212, 212, 212); font-family: Consolas, &quot;Courier New&quot;, monospace; font-size: 14px; line-height: 19px; white-space: pre;\"><div><span style=\"color: rgb(128, 128, 128);\">&lt;!</span><span style=\"color: rgb(86, 156, 214);\">DOCTYPE</span> <span style=\"color: rgb(156, 220, 254);\">html</span><span style=\"color: rgb(128, 128, 128);\">&gt;</span></div><div><span style=\"color: rgb(128, 128, 128);\">&lt;</span><span style=\"color: rgb(86, 156, 214);\">html</span> <span style=\"color: rgb(156, 220, 254);\">lang</span>=<span style=\"color: rgb(206, 145, 120);\">\"en\"</span><span style=\"color: rgb(128, 128, 128);\">&gt;</span></div><div><span style=\"color: rgb(128, 128, 128);\">&lt;</span><span style=\"color: rgb(86, 156, 214);\">head</span><span style=\"color: rgb(128, 128, 128);\">&gt;</span></div><div>&nbsp; &nbsp; <span style=\"color: rgb(128, 128, 128);\">&lt;</span><span style=\"color: rgb(86, 156, 214);\">title</span><span style=\"color: rgb(128, 128, 128);\">&gt;</span>Insert Data in PHP MySQL<span style=\"color: rgb(128, 128, 128);\">&lt;/</span><span style=\"color: rgb(86, 156, 214);\">title</span><span style=\"color: rgb(128, 128, 128);\">&gt;</span></div><div>&nbsp; &nbsp; <span style=\"color: rgb(128, 128, 128);\">&lt;</span><span style=\"color: rgb(86, 156, 214);\">link</span> <span style=\"color: rgb(156, 220, 254);\">href</span>=<span style=\"color: rgb(206, 145, 120);\">\"https://cdn.jsdelivr.net/npm/bootstrap@5.1.3/dist/css/bootstrap.min.css\"</span> <span style=\"color: rgb(156, 220, 254);\">rel</span>=<span style=\"color: rgb(206, 145, 120);\">\"stylesheet\"</span> <span style=\"color: rgb(128, 128, 128);\">/&gt;</span></div><div><span style=\"color: rgb(128, 128, 128);\">&lt;/</span><span style=\"color: rgb(86, 156, 214);\">head</span><span style=\"color: rgb(128, 128, 128);\">&gt;</span></div><div><span style=\"color: rgb(128, 128, 128);\">&lt;</span><span style=\"color: rgb(86, 156, 214);\">body</span><span style=\"color: rgb(128, 128, 128);\">&gt;</span></div><div>&nbsp; &nbsp; </div><div>&nbsp; &nbsp; <span style=\"color: rgb(128, 128, 128);\">&lt;</span><span style=\"color: rgb(86, 156, 214);\">div</span> <span style=\"color: rgb(156, 220, 254);\">class</span>=<span style=\"color: rgb(206, 145, 120);\">\"container mt-5\"</span><span style=\"color: rgb(128, 128, 128);\">&gt;</span></div><div>&nbsp; &nbsp; &nbsp; &nbsp; <span style=\"color: rgb(128, 128, 128);\">&lt;</span><span style=\"color: rgb(86, 156, 214);\">div</span> <span style=\"color: rgb(156, 220, 254);\">class</span>=<span style=\"color: rgb(206, 145, 120);\">\"row justify-content-center\"</span><span style=\"color: rgb(128, 128, 128);\">&gt;</span></div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; <span style=\"color: rgb(128, 128, 128);\">&lt;</span><span style=\"color: rgb(86, 156, 214);\">div</span> <span style=\"color: rgb(156, 220, 254);\">class</span>=<span style=\"color: rgb(206, 145, 120);\">\"col-md-6\"</span><span style=\"color: rgb(128, 128, 128);\">&gt;</span></div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; <span style=\"color: rgb(128, 128, 128);\">&lt;</span><span style=\"color: rgb(86, 156, 214);\">div</span> <span style=\"color: rgb(156, 220, 254);\">class</span>=<span style=\"color: rgb(206, 145, 120);\">\"card shadow\"</span><span style=\"color: rgb(128, 128, 128);\">&gt;</span></div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; <span style=\"color: rgb(128, 128, 128);\">&lt;</span><span style=\"color: rgb(86, 156, 214);\">div</span> <span style=\"color: rgb(156, 220, 254);\">class</span>=<span style=\"color: rgb(206, 145, 120);\">\"card-header\"</span><span style=\"color: rgb(128, 128, 128);\">&gt;</span></div><div>&nbsp; &nbsp; &nbsp;