n>=<span style=\"color: rgb(206, 145, 120);\">\"submit\"</span> <span style=\"color: rgb(156, 220, 254);\">name</span>=<span style=\"color: rgb(206, 145, 120);\">\"insert_buttton\"</span> <span style=\"color: rgb(156, 220, 254);\">class</span>=<span style=\"color: rgb(206, 145, 120);\">\"btn btn-primary\"</span><span style=\"color: rgb(128, 128, 128);\">&gt;</span>Insert Data<span style=\"color: rgb(128, 128, 128);\">&lt;/</span><span style=\"color: rgb(86, 156, 214);\">button</span><span style=\"color: rgb(128, 128, 128);\">&gt;</span></div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; <span style=\"color: rgb(128, 128, 128);\">&lt;/</span><span style=\"color: rgb(86, 156, 214);\">div</span><span style=\"color: rgb(128, 128, 128);\">&gt;</span></div><br><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; <span style=\"color: rgb(128, 128, 128);\">&lt;/</span><span style=\"color: rgb(86, 156, 214);\">form</span><span style=\"color: rgb(128, 128, 128);\">&gt;</span></div><br><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; <span style=\"color: rgb(128, 128, 128);\">&lt;/</span><span style=\"color: rgb(86, 156, 214);\">div</span><span style=\"color: rgb(128, 128, 128);\">&gt;</span></div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; <span style=\"color: rgb(128, 128, 128);\">&lt;/</span><span style=\"color: rgb(86, 156, 214);\">div</span><span style=\"color: rgb(128, 128, 128);\">&gt;</span></div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; <span style=\"color: rgb(128, 128, 128);\">&lt;/</span><span style=\"color: rgb(86, 156, 214);\">div</span><span style=\"color: rgb(128, 128, 128);\">&gt;</span></div><div>&nbsp; &nbsp; &nbsp; &nbsp; <span style=\"color: rgb(128, 128, 128);\">&lt;/</span><span style=\"color: rgb(86, 156, 214);\">div</span><span style=\"color: rgb(128, 128, 128);\">&gt;</span></div><div>&nbsp; &nbsp; <span style=\"color: rgb(128, 128, 128);\">&lt;/</span><span style=\"color: rgb(86, 156, 214);\">div</span><span style=\"color: rgb(128, 128, 128);\">&gt;</span></div><br><div>&nbsp; &nbsp; <span style=\"color: rgb(128, 128, 128);\">&lt;</span><span style=\"color: rgb(86, 156, 214);\">script</span> <span style=\"color: rgb(156, 220, 254);\">src</span>=<span style=\"color: rgb(206, 145, 120);\">\"https://code.jquery.com/jquery-3.6.0.min.js\"</span><span style=\"color: rgb(128, 128, 128);\">&gt;&lt;/</span><span style=\"color: rgb(86, 156, 214);\">script</span><span style=\"color: rgb(128, 128, 128);\">&gt;</span></div><div>&nbsp; &nbsp; <span style=\"color: rgb(128, 128, 128);\">&lt;</span><span style=\"color: rgb(86, 156, 214);\">script</span> <span style=\"color: rgb(156, 220, 254);\">src</span>=<span style=\"color: rgb(206, 145, 120);\">\"https://cdn.jsdelivr.net/npm/bootstrap@5.1.3/dist/js/bootstrap.bundle.min.js\"</span><span style=\"color: rgb(128, 128, 128);\">&gt;&lt;/</span><span style=\"color: rgb(86, 156, 214);\">script</span><span style=\"color: rgb(128, 128, 128);\">&gt;</span></div><div><span style=\"color: rgb(128, 128, 128);\">&lt;/</span><span style=\"color: rgb(86, 156, 214);\">body</span><span style=\"color: rgb(128, 128, 128);\">&gt;</span></div><div><span style=\"color: rgb(128, 128, 128);\">&lt;/</span><span style=\"color: rgb(86, 156, 214);\">html</span><span style=\"color: rgb(128, 128, 128);\">&gt;</span></div></div><p style=\"margin-bottom: 16px; line-height: 24px; font-size: 16px; color: rgb(33, 37, 41); font-family: Poppins, sans-serif;\"><br></p><p style=\"margin-bottom: 16px; line-height: 24px; font-size: 16px; color: rgb(33, 37, 41); font-family: Poppins, sans-serif;\"><span style=\"font-weight: bolder;\">Step 3:&nbsp;</span>Create a file named&nbsp;<span style=\"font-weight: bolder;\">code.php</span>&nbsp;to write the code to save data into database in php mysql.</p><div class=\"alert funda-bg\" style=\"width: fit-content; min-width: 100%; background-color: rgb(30, 30, 30); color: rgb(212, 212, 212); font-family: Consolas, &quot;Courier New&quot;, monospace; font-size: 14px; line-height: 19px; white-space: pre;\"><div><span style=\"color: rgb(86, 156, 214);\">&lt;?php</span></div><div>&nbsp; &nbsp; <span style=\"color: rgb(197, 134, 192);\">include_once</span> <span style=\"color: rgb(206, 145, 120);\">\'dbconfig.php\'</span>;</div><br><div>&nbsp; &nbsp; <span style=\"color: rgb(197, 134, 192);\">if</span>(<span style=\"color: rgb(220, 220, 170);\">isset</span>(<span style=\"color: rgb(156, 220, 254);\">$_POST</span>[<span style=\"color: rgb(206, 145, 120);\">\'insert_buttton\'</span>]))</div><div>&nbsp; &nbsp; { &nbsp; &nbsp;</div><div>&nbsp; &nbsp; &nbsp; &nbsp; <span style=\"color: rgb(156, 220, 254);\">$fullname</span> = <span style=\"color: rgb(156, 220, 254);\">$_POST</span>[<span style=\"color: rgb(206, 145, 120);\">\'fullname\'</span>];</div><div>&nbsp; &nbsp; &nbsp; &nbsp; <span style=\"color: rgb(156, 220, 254);\">$course</span> = <span style=\"color: rgb(156, 220, 254);\">$_POST</span>[<span style=\"color: rgb(206, 145, 120);\">\'course\'</span>];</div><div>&nbsp; &nbsp; &nbsp; &nbsp; <span style=\"color: rgb(156, 220, 254);\">$email</span> = <span style=\"color: rgb(156, 220, 254);\">$_POST</span>[<span style=\"color: rgb(206, 145, 120);\">\'email\'</span>];</div><br><div>&nbsp; &nbsp; &nbsp; &nbsp; <span style=\"color: rgb(156, 220, 254);\">$query</span> = <span style=\"color: rgb(206, 145, 120);\">\"</span><span style=\"color: rgb(86, 156, 214);\">INSERT</span><span style=\"color: rgb(206, 145, 120);\"> </span><span style=\"color: rgb(86, 156, 214);\">INTO</span><span style=\"color: rgb(206, 145, 120);\"> students (fullname,course,email) </span><span style=\"color: rgb(86, 156, 214);\">VALUES</span><span style=\"color: rgb(206, 145, 120);\"> (\'</span><span style=\"color: rgb(156, 220, 254);\">$fullname</span><span style=\"color: rgb(206, 145, 120);\">\',\'</span><span style=\"color: rgb(156, 220, 254);\">$course</span><span style=\"color: rgb(206, 145, 120);\">\',\'</span><span style=\"color: rgb(156, 220, 254);\">$email</span><span style=\"color: rgb(206, 145, 120);\">\')</span><span style=\"color: rgb(206, 145, 120);\">\"</span>;</div><div>&nbsp; &nbsp; &nbsp; &nbsp; <span style=\"color: rgb(156, 220, 254);\">$result</span> = <span style=\"color: rgb(220, 220, 170);\">mysqli_query</span>(<span style=\"color: rgb(156, 220, 254);\">$conn</span>, <span style=\"color: rgb(156, 220, 254);\">$query</span>); </div><div>&nbsp; &nbsp; &nbsp; &nbsp; <span style=\"color: rgb(197, 134, 192);\">if</span>(<span style=\"color: rgb(156, 220, 254);\">$result</span>) </div><div>&nbsp; &nbsp; &nbsp; &nbsp; {</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; <span style=\"color: rgb(220, 220, 170);\">echo</span> <span style=\"color: rgb(206, 145, 120);\">\"Data Inserted Successfully!\"</span>;</div><div>&nbsp; &nbsp; &nbsp; &nbsp; } </div><div>&nbsp; &nbsp; &nbsp; &nbsp; <span style=\"color: rgb(197, 134, 192);\">else</span></div><div>&nbsp; &nbsp; &nbsp; &nbsp; {</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; <span style=\"color: rgb(220, 220, 170);\">echo</span> <span style=\"color: rgb(206, 145, 120);\">\"Data Not Inserted!. Error: \"</span> . <span style=\"color: rgb(156, 220, 254);\">$sql</span> . <span style=\"color: rgb(206, 145, 120);\">\"\"</span> . <span style=\"color: rgb(220, 220, 170);\">mysqli_error</span>(<span style=\"color: rgb(156, 220, 254);\">$conn</span>);</div><div>&nbsp; &nbsp; &nbsp; &nbsp; }</div><div>&nbsp; &nbsp; }</div><div><span style=\"color: rgb(86, 156, 214);\">?</span><span style=\"color: rgb(86, 156, 214);\">&gt;</span></div></div><p style=\"margin-bottom: 16px; line-height: 24px; font-size: 16px; color: rgb(33, 37, 41); font-family: Poppins, sans-serif;\"><br></p><p style=\"margin-bottom: 16px; line-height: 24px; font-size: 16px; color: rgb(33, 37, 41); font-family: Poppins, sans-serif;\">That\'s it. We successfully stored the Data.</p><p style=\"margin-bottom: 16px; line-height: 24px; font-size: 16px; color: rgb(33, 37, 41); font-family: Poppins, sans-serif;\"><span style=\"font-weight: bolder;\">Thanks for reading.</span></p></h3><div><p></p><p></p></div><p></p><p><!--?php</p--></p>', '1634289493.jpg', 'PHP Insert Data', 'PHP Insert data into database', 'PHP Insert data into database', 0, '2021-10-15 09:18:13');
INSERT INTO `posts` (`id`, `category_id`, `name`, `slug`, `description`, `image`, `meta_title`, `meta_description`, `meta_keyword`, `status`, `created_at`) VALUES
(4, 2, 'PHP Fetch data from database in php', 'php-fetch-data-from-database-in-php-mysql', '<p style=\"margin-bottom: 16px; line-height: 24px; color: rgb(33, 37, 41); font-family: Poppins, sans-serif;\">How to get data from database in php mysql</p><p style=\"margin-bottom: 16px; line-height: 24px; color: rgb(33, 37, 41); font-family: Poppins, sans-serif;\">In this tutorial, you will learn how to get / retrieve data from database in php mysql, so we will create a html table format to fetch data in it using php mysql.</p><p style=\"margin-bottom: 16px; line-height: 24px; color: rgb(33, 37, 41); font-family: Poppins, sans-serif;\">So guys, to fetch data make sure you have created your database &amp; table.</p><p style=\"margin-bottom: 16px; line-height: 24px; color: rgb(33, 37, 41); font-family: Poppins, sans-serif;\"><span style=\"font-weight: bolder;\">Step 1.</span>&nbsp;Create your database connection in&nbsp;<span style=\"font-weight: bolder;\">dbconfig.php&nbsp;</span>file:</p><div class=\"alert funda-bg\" style=\"width: fit-content; min-width: 100%; background-color: rgb(30, 30, 30); color: rgb(212, 212, 212); font-family: Consolas, &quot;Courier New&quot;, monospace; font-size: 14px; line-height: 19px; white-space: pre;\"><div><span style=\"color: rgb(86, 156, 214);\">&lt;?php</span></div><div>&nbsp; &nbsp; <span style=\"color: rgb(156, 220, 254);\">$host</span> = <span style=\"color: rgb(206, 145, 120);\">\"localhost\"</span>;</div><div>&nbsp; &nbsp; <span style=\"color: rgb(156, 220, 254);\">$username</span> = <span style=\"color: rgb(206, 145, 120);\">\"your_username\"</span>;</div><div>&nbsp; &nbsp; <span style=\"color: rgb(156, 220, 254);\">$password</span> = <span style=\"color: rgb(206, 145, 120);\">\"your_password\"</span>;</div><div>&nbsp; &nbsp; <span style=\"color: rgb(156, 220, 254);\">$database</span> = <span style=\"color: rgb(206, 145, 120);\">\"your_database_name\"</span>;</div><br><div>&nbsp; &nbsp; <span style=\"color: rgb(106, 153, 85);\">// Create DB Connection</span></div><div>&nbsp; &nbsp; <span style=\"color: rgb(156, 220, 254);\">$conn</span> = <span style=\"color: rgb(220, 220, 170);\">mysqli_connect</span>(<span style=\"color: rgb(156, 220, 254);\">$host</span>, <span style=\"color: rgb(156, 220, 254);\">$username</span>, <span style=\"color: rgb(156, 220, 254);\">$password</span>, <span style=\"color: rgb(156, 220, 254);\">$database</span>);</div><br><div>&nbsp; &nbsp; <span style=\"color: rgb(106, 153, 85);\">// Check connection</span></div><div>&nbsp; &nbsp; <span style=\"color: rgb(197, 134, 192);\">if</span> (!<span style=\"color: rgb(156, 220, 254);\">$conn</span>) {</div><div>&nbsp; &nbsp; &nbsp; &nbsp; <span style=\"color: rgb(197, 134, 192);\">die</span>(<span style=\"color: rgb(206, 145, 120);\">\"Connection failed: \"</span> . <span style=\"color: rgb(220, 220, 170);\">mysqli_connect_error</span>());</div><div>&nbsp; &nbsp; }</div><div><span style=\"color: rgb(86, 156, 214);\">?</span><span style=\"color: rgb(86, 156, 214);\">&gt;</span></div></div><p style=\"margin-bottom: 16px; line-height: 24px; color: rgb(33, 37, 41); font-family: Poppins, sans-serif;\"><span style=\"font-weight: bolder;\">Step 2:</span>&nbsp;Create a file&nbsp;<span style=\"font-weight: bolder;\">index.php</span>&nbsp;and fetch data in it and we are using bootstrap v5 to design the User Interface:</p><div class=\"alert funda-bg\" style=\"width: fit-content; min-width: 100%; background-color: rgb(30, 30, 30); color: rgb(212, 212, 212); font-family: Consolas, &quot;Courier New&quot;, monospace; font-size: 14px; line-height: 19px; white-space: pre;\"><div style=\"line-height: 19px;\"><div><span style=\"color: rgb(128, 128, 128);\">&lt;!</span><span style=\"color: rgb(86, 156, 214);\">DOCTYPE</span> <span style=\"color: rgb(156, 220, 254);\">html</span><span style=\"color: rgb(128, 128, 128);\">&gt;</span></div><div><span style=\"color: rgb(128, 128, 128);\">&lt;</span><span style=\"color: rgb(86, 156, 214);\">html</span> <span style=\"color: rgb(156, 220, 254);\">lang</span>=<span style=\"color: rgb(206, 145, 120);\">\"en\"</span><span style=\"color: rgb(128, 128, 128);\">&gt;</span></div><div><span style=\"color: rgb(128, 128, 128);\">&lt;</span><span style=\"color: rgb(86, 156, 214);\">head</span><span style=\"color: rgb(128, 128, 128);\">&gt;</span></div><div>&nbsp; &nbsp; <span style=\"color: rgb(128, 128, 128);\">&lt;</span><span style=\"color: rgb(86, 156, 214);\">title</span><span style=\"color: rgb(128, 128, 128);\">&gt;</span>Fetch Data in PHP MySQL<span style=\"color: rgb(128, 128, 128);\">&lt;/</span><span style=\"color: rgb(86, 156, 214);\">title</span><span style=\"color: rgb(128, 128, 128);\">&gt;</span></div><div>&nbsp; &nbsp; <span style=\"color: rgb(128, 128, 128);\">&lt;</span><span style=\"color: rgb(86, 156, 214);\">link</span> <span style=\"color: rgb(156, 220, 254);\">href</span>=<span style=\"color: rgb(206, 145, 120);\">\"https://cdn.jsdelivr.net/npm/bootstrap@5.1.3/dist/css/bootstrap.min.css\"</span> <span style=\"color: rgb(156, 220, 254);\">rel</span>=<span style=\"color: rgb(206, 145, 120);\">\"stylesheet\"</span> <span style=\"color: rgb(128, 128, 128);\">/&gt;</span></div><div><span style=\"color: rgb(128, 128, 128);\">&lt;/</span><span style=\"color: rgb(86, 156, 214);\">head</span><span style=\"color: rgb(128, 128, 128);\">&gt;</span></div><div><span style=\"color: rgb(128, 128, 128);\">&lt;</span><span style=\"color: rgb(86, 156, 214);\">body</span><span style=\"color: rgb(128, 128, 128);\">&gt;</span></div><div>&nbsp; &nbsp; </div><div>&nbsp; &nbsp; <span style=\"color: rgb(128, 128, 128);\">&lt;</span><span style=\"color: rgb(86, 156, 214);\">div</span> <span style=\"color: rgb(156, 220, 254);\">class</span>=<span style=\"color: rgb(206, 145, 120);\">\"container mt-5\"</span><span style=\"color: rgb(128, 128, 128);\">&gt;</span></div><div>&nbsp; &nbsp; &nbsp; &nbsp; <span style=\"color: rgb(128, 128, 128);\">&lt;</span><span style=\"color: rg